 private static boolean blocked(String host){if(host==null)return false;for(String bad:new String[]{"doubleclick.net","googlesyndication.com","popads.net","popcash.net","googleadservices.com","adsco.re"})if(host.equals(bad)||host.endsWith("."+bad))return true;return false;}
 private void reset(){++generation;probing=false;listing=false;searching=false;opening=false;resolverTarget="";seen.clear();visited.clear();alternatives.clear();playerHops=0;lastStage="";web.stopLoading();ui.removeCallbacksAndMessages(null);}
 private void loadSite(){try{String raw=domain.getText().toString().trim();URI u=new URI(raw);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null)throw new Exception();reset();saveDomain(raw);note("URL salvato · inserisci il titolo e premi Cerca");}catch(Exception e){note("Inserisci un URL HTTPS valido");}}
 private String searchTerm="";
 private void search(){String q=query.getText().toString().trim();if(q.isEmpty()){catalogue();return;}try{URI u=new URI(domain.getText().toString().trim());if(!"https".equals(u.getScheme())||u.getHost()==null)throw new Exception();reset();sourceRows.clear();searchTerm=q;results.removeAllViews();searching=true;int request=generation;saveDomain(u.toString());note("Ricerca dei film…");if(siteIndex==1){web.loadUrl(u.resolve("/").toString());ui.postDelayed(()->submitNativeSearch(q,request,0),1800);}else{web.loadUrl(u.resolve("/").toString()+"?s="+java.net.URLEncoder.encode(q,"UTF-8"));ui.postDelayed(()->collectResults(request,0),1500);}}catch(Exception e){note("Inserisci un URL HTTPS valido");}}
 private void submitNativeSearch(String q,int request,int attempt){if(destroyed||request!=generation||!searching)return;web.evaluateJavascript(VodWebSearchScript.submit(JSONObject.quote(q)),value->{if(request!=generation||destroyed)return;if("true".equals(value))ui.postDelayed(()->collectResults(request,0),1800);else if(attempt<10)ui.postDelayed(()->submitNativeSearch(q,request,attempt+1),700);else note("Ricerca della fonte non disponibile · prova Catalogo");});}
 private void collectResults(int request,int attempt){if(destroyed||request!=generation||!searching)return;
  String script=catalogScript+"("+JSONObject.quote(searchTerm)+")";
  web.evaluateJavascript(script,raw->{if(destroyed||request!=generation||!searching)return;try{JSONArray found=new JSONArray(new JSONArray("["+raw+"]").getString(0));if(found.length()>0){searching=false;note("Seleziona un film · "+found.length()+" risultati");cachedCards=found;showCards(found,request);if(results.getChildCount()>0&&results.getChildAt(0) instanceof LinearLayout){ViewGroup cards=(ViewGroup)results.getChildAt(0);if(cards.getChildCount()>0)cards.getChildAt(0).requestFocus();}return;}}catch(Exception ignored){}if(attempt<16)ui.postDelayed(()->collectResults(request,attempt+1),1000);else{searching=false;if(!pageError)note("Nessun titolo trovato · verifica il titolo o l’URL della fonte");}});
 }
 private String asset(String name){try(java.io.InputStream in=getAssets().open(name);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}catch(Exception e){return "(function(){return '[]'})";}}
