  for(int i=0;i<found.length();i++){if(i%cols==0){row=new LinearLayout(this);results.addView(row);}JSONObject item=found.getJSONObject(i);String title=item.getString("title"),url=item.getString("url"),image=item.optString("image");LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(5),dp(5),dp(5),dp(8));row.addView(card,new LinearLayout.LayoutParams(0,dp(275),1));ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);poster.setBackgroundColor(0xff292b31);poster.setContentDescription(title);card.addView(poster,new LinearLayout.LayoutParams(-1,dp(215)));TextView label=new TextView(this);label.setText(title);label.setTextColor(Color.WHITE);label.setTextSize(13);label.setMaxLines(3);card.addView(label);card.setFocusable(true);card.setClickable(true);card.setBackground(cardFocus());card.setOnClickListener(v->openMovie(title,url));poster.setFocusable(false);label.setFocusable(false);if(image.startsWith("https://"))images.submit(()->{try(Response r=CbTransport.HTTP.newCall(new Request.Builder().url(image).header("User-Agent",userAgent).header("Referer",domainText()).build()).execute()){if(r.isSuccessful()&&r.body()!=null){android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeStream(r.body().byteStream());runOnUiThread(()->{if(!destroyed&&request==generation&&bitmap!=null)poster.setImageBitmap(bitmap);});}}catch(Exception ignored){}});
  }if(row!=null)for(int n=found.length()%cols;n>0&&n<cols;n++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
