 private String domainText(){try{return new URI(filmPage.isEmpty()?homes[siteIndex]:filmPage).resolve("/").toString();}catch(Exception e){return homes[0];}}
 private int siteIndex;
 private void openMovie(String title,String url){if(movieJson==null||!url.equals(movieJson.optString("_web_page")))try{movieJson=new JSONObject().put("id",String.valueOf(Integer.toUnsignedLong(url.hashCode()))).put("name",title).put("type","movie").put("slug","cb01").put("_web_page",url);if(cachedCards!=null)for(int i=0;i<cachedCards.length();i++){JSONObject card=cachedCards.optJSONObject(i);if(card!=null&&url.equals(card.optString("url")))movieJson.put("_poster_url",card.optString("image"));}}catch(Exception ignored){}reset();sourceRows.clear();query.setText(title);filmPage=url;listing=true;results.removeAllViews();Button back=button("‹ Catalogo R. ITA");back.setOnClickListener(v->{if(getIntent().hasExtra("moviePage"))finish();else backToCards();});results.addView(back);TextView name=new TextView(this);name.setText(title+"\nFonti video");name.setTextColor(Color.WHITE);name.setTextSize(20);name.setPadding(dp(12),dp(12),dp(12),dp(12));results.addView(name);note("Caricamento delle fonti del film…");int request=generation;web.loadUrl(url);ui.postDelayed(()->collectChoices(request,0),2000);}
 private void backToCards(){sourceRows.clear();reset();results.removeAllViews();try{if(cachedCards!=null){showCards(cachedCards,generation);note("Seleziona un film");}else catalogue();}catch(Exception e){catalogue();}}
 private void collectChoices(int request,int attempt){if(destroyed||request!=generation||!listing)return;web.evaluateJavascript(VodWebSearchScript.snapshot(),raw->{if(destroyed||request!=generation||!listing)return;try{JSONObject page=new JSONObject(new JSONArray("["+raw+"]").getString(0));for(CbStreamChoices.Choice c:CbStreamChoices.parse(page.optString("html"),page.optString("url")))addChoice(c);if(!sourceRows.isEmpty())note("Seleziona una fonte per avviare il player");}catch(Exception ignored){}if(sourceRows.isEmpty()&&attempt<12)ui.postDelayed(()->collectChoices(request,attempt+1),1000);else if(sourceRows.isEmpty()&&!pageError)note("Nessuna fonte video trovata nella scheda del film");});}
 private void addChoice(CbStreamChoices.Choice choice){if(sourceRows.containsKey(choice.url))return;String display=choice.label;int same=0;for(Button existing:sourceRows.values())if(existing.getText().toString().startsWith(choice.label+" ·")||existing.getText().toString().startsWith(choice.label+" ("))same++;if(same>0)display+=" ("+(same+1)+")";Button row=button(display+" · "+(choice.direct?"Flusso diretto":"Fonte da risolvere"));row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);results.addView(row,new LinearLayout.LayoutParams(-1,dp(62)));sourceRows.put(choice.url,row);if(!CbLinkTargets.mixdrop(choice.url)&&!CbLinkTargets.stay(choice.url)){row.setText(display+" · estrazione non ancora supportata");row.setOnClickListener(v->note("Per ora è supportato soltanto Mixdrop"));}else row.setOnClickListener(v->resolveChoice(choice,row));row.setOnLongClickListener(v->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("Link fonte",choice.url));Toast.makeText(this,"Link della fonte copiato",Toast.LENGTH_SHORT).show();return true;});}
 private void resolveChoice(CbStreamChoices.Choice choice,Button row){reset();resolverTarget=CbLinkTargets.embed(choice.url);activeSource=row;activeName=choice.label;probing=true;int request=generation;row.setText(choice.label+" · Estrazione…");if(CbLinkTargets.mixdrop(choice.url))openResolved(resolverTarget,origin(filmPage),request,row);else if(CbLinkTargets.stay(choice.url)){note("Risoluzione del collegamento Mixdrop…");worker.submit(()->{try{String target=CbStayResolver.resolve(choice.url,origin(filmPage),CbMixdropResolver.USER_AGENT);runOnUiThread(()->{if(destroyed||request!=generation||!probing)return;if(!CbLinkTargets.mixdrop(target)){probing=false;row.setText(choice.label+" · estrazione non ancora supportata");note("Per ora è supportato soltanto Mixdrop");return;}resolverTarget=target;openResolved(target,origin(choice.url),request,row);});}catch(Exception e){runOnUiThread(()->{if(destroyed||request!=generation)return;probing=false;row.setText(choice.label+" · Non disponibile");note(e.getMessage()==null?"Collegamento non risolto":e.getMessage());});}});}else{probing=false;note("Per ora è supportato soltanto Mixdrop");}ui.postDelayed(()->{if(request==generation&&probing&&!opening){probing=false;row.setText(choice.label+" · Tempo di attesa terminato");note("Riprova la fonte Mixdrop");}},75000);}
 private void openResolved(String target,String parent,int request,Button row){
  if(!CbLinkTargets.mixdrop(target)){probing=false;note("Per ora è supportato soltanto Mixdrop");return;}
  lastStage="Mixdrop · lettura della configurazione video";note(lastStage);
  worker.submit(()->{try{CbMixdropResolver.Result result=CbMixdropResolver.resolve(target,parent,userAgent);runOnUiThread(()->{if(destroyed||request!=generation||!probing||opening)return;resolverTarget=result.page;Map<String,String> headers=new HashMap<>();headers.put("Referer",result.page);headers.put("Origin",origin(result.page).replaceAll("/$",""));headers.put("User-Agent",CbMixdropResolver.USER_AGENT);lastStage="Mixdrop · verifica del flusso MP4";note(lastStage);detect(result.url,headers,true);});}catch(Exception e){runOnUiThread(()->{if(destroyed||request!=generation||!probing)return;probing=false;lastStage=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();row.setText(activeName+" · Non disponibile, riprova");note(lastStage);});}});
 }
 private String origin(String url){try{return new URI(url).resolve("/").toString();}catch(Exception e){return domainText();}}
 private void saveDomain(String raw){try{String base=VodSource.base(raw);java.util.List<VodSettings.Source> sources=VodSettings.sources(this);VodSettings.Source current=VodSettings.cb01(this);boolean found=false;for(int i=0;i<sources.size();i++)if(sources.get(i).id.equals(current.id)){sources.set(i,new VodSettings.Source(current.id,current.name,base,"web"));found=true;}if(!found)sources.add(new VodSettings.Source(current.id,current.name,base,"web"));VodSettings.prefs(this).edit().putBoolean("manual_"+current.id,true).apply();VodSettings.save(this,sources);cbSource=VodSettings.cb01(this);}catch(Exception ignored){}}
 private android.graphics.drawable.Drawable cardFocus(){android.graphics.drawable.StateListDrawable d=new android.graphics.drawable.StateListDrawable();android.graphics.drawable.GradientDrawable f=new android.graphics.drawable.GradientDrawable();f.setColor(UiTheme.softFocus(this));f.setStroke(dp(3),UiTheme.accent(this));d.addState(new int[]{android.R.attr.state_focused},f);d.addState(new int[]{},new android.graphics.drawable.ColorDrawable(UiTheme.panel(this)));return d;}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==142){opening=false;setResult(result,data);}}
 private static boolean validHttps(String url){try{URI u=new URI(url);return "https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&!WebMovieLinks.trailer(url);}catch(Exception e){return false;}}
 private static boolean candidate(String url){if(WebMovieLinks.media(url))return true;try{URI u=new URI(url);return "https".equals(u.getScheme())&&u.getHost()!=null&&!WebMovieLinks.trailer(url)&&u.getPath().matches("(?i).*/(?:master|manifest|playlist|videoplayback)(?:[./].*)?");}catch(Exception e){return false;}}
 private void detect(String url,Map<String,String> requestHeaders){detect(url,requestHeaders,false);}
 private void detect(String url,Map<String,String> requestHeaders,boolean exposed){if(destroyed||opening||!CbLinkTargets.ownsMedia(resolverTarget,url)||!(candidate(url)||(exposed&&validHttps(url)))||seen.size()>=24||!seen.add(url))return;final int request=generation;Map<String,String> headers=new HashMap<>();
  for(Map.Entry<String,String> h:requestHeaders.entrySet())for(String key:new String[]{"Referer","Origin","User-Agent"})if(key.equalsIgnoreCase(h.getKey()))headers.put(key,h.getValue());headers.putIfAbsent("Referer",filmPage);headers.putIfAbsent("User-Agent",userAgent);String cookies=CookieManager.getInstance().getCookie(url);if(cookies!=null&&!cookies.isEmpty())headers.put("Cookie",cookies);
  worker.submit(()->{if(destroyed||request!=generation||!probing||opening)return;try{boolean mp4=new URI(url).getPath().toLowerCase(Locale.ROOT).endsWith(".mp4");Request.Builder b=new Request.Builder().url(url);for(Map.Entry<String,String> h:headers.entrySet())b.header(h.getKey(),h.getValue());if(mp4||exposed)b.header("Range","bytes=0-8191");
   try(Response r=CbTransport.HTTP.newCall(b.build()).execute()){if(destroyed||request!=generation)return;if(!r.isSuccessful()||r.body()==null){lastStage="Video HTTP "+r.code()+" · "+new URI(url).getHost();note(lastStage);return;}String type=r.header("Content-Type","");byte[] signature=r.peekBody(32).bytes();if(type.startsWith("video/")||(signature.length>=8&&signature[4]==102&&signature[5]==116&&signature[6]==121&&signature[7]==112))mp4=true;if(mp4){if(!type.startsWith("video/")&&!type.contains("octet-stream")){note("Il server non restituisce un video MP4");return;}}else{String first=r.body().source().readUtf8LineStrict(4096);if(first==null||!first.replace("\uFEFF","").trim().equals("#EXTM3U")){note("La risposta non è una playlist HLS");return;}}}
   final boolean progressive=mp4;runOnUiThread(()->{if(destroyed||request!=generation||opening)return;opening=true;probing=false;web.stopLoading();web.evaluateJavascript("document.querySelectorAll('video,audio').forEach(function(v){v.pause()})",null);note("Flusso verificato · apertura Media3");startActivityForResult(new Intent(this,VodPlayerActivity.class).putExtra("source",cbSource.json().toString()).putExtra("titleJson",movieJson.toString()).putExtra("episode","").putExtra("label",movieJson.optString("name")).putExtra("episodes","[]").putExtra("index",-1).putExtra("resolvedWebUrl",url).putExtra("resolvedWebHeaders",new JSONObject(headers).toString()).putExtra("startPosition",getIntent().getLongExtra("startPosition",-1)),142);});
  }catch(Exception e){if(!destroyed&&request==generation)note("Video non verificato · "+e.getClass().getSimpleName());}});
 }
 @Override public void onBackPressed(){if(getIntent().hasExtra("moviePage")){finish();}else if(!sourceRows.isEmpty()){sourceRows.clear();backToCards();}else{reset();super.onBackPressed();}}
 @Override protected void onPause(){super.onPause();web.onPause();CookieManager.getInstance().flush();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();opening=false;if(catalogAtOpen!=null&&!catalogAtOpen.equals(VodSession.catalogue(this).id)){startActivity(new Intent(this,VodActivity.class));finish();}}
 @Override protected void onDestroy(){destroyed=true;++generation;ui.removeCallbacksAndMessages(null);worker.shutdownNow();images.shutdownNow();web.stopLoading();web.destroy();super.onDestroy();}
